import React, { useState } from "react";
import { useParams, Link } from "react-router-dom";
import { Box, Typography, Button, TextField, Chip } from "@mui/material";
import simulations from "./Simulations";
import { ZB_COLORS } from "./theme";

export default function SimulationRunner() {
  const { simId } = useParams();
  const sim = simulations.find(s => s.id === simId);
  const [activeStep, setActiveStep] = useState(0);
  const [answers, setAnswers] = useState({});
  const [submitted, setSubmitted] = useState(false);

  if (!sim) {
    return (
      <Box sx={{ textAlign: "center", py: 10 }}>
        <Typography variant="h5" sx={{ color: "#fff", mb: 2 }}>Simulation not found</Typography>
        <Button component={Link} to="/simulations" variant="contained">Back to simulations</Button>
      </Box>
    );
  }

  const task = sim.tasks[activeStep];
  const isLast = activeStep === sim.tasks.length - 1;

  const handleNext = () => {
    if (isLast) setSubmitted(true);
    else setActiveStep(prev => prev + 1);
  };

  if (submitted) {
    return (
      <Box sx={{ maxWidth: 600, mx: "auto", px: 2, py: 8, textAlign: "center" }}>
        <Box sx={{ fontSize: "3rem", mb: 2 }}>🎉</Box>
        <Typography variant="h4" sx={{ color: "#fff", mb: 1 }}>Simulation complete!</Typography>
        <Typography sx={{ color: ZB_COLORS.textMuted, fontFamily: "DM Sans", mb: 3 }}>
          You've completed all {sim.tasks.length} tasks in {sim.title}. Great work!
        </Typography>
        <Button component={Link} to="/simulations" variant="contained" sx={{ mr: 1 }}>More simulations</Button>
        <Button component={Link} to="/dashboard" sx={{ color: "rgba(255,255,255,0.6)", border: `0.5px solid ${ZB_COLORS.border}`, borderRadius: "8px", px: 2 }}>
          Dashboard
        </Button>
      </Box>
    );
  }

  return (
    <Box sx={{ maxWidth: 760, mx: "auto", px: { xs: 2, md: 3 }, py: { xs: 4, md: 6 } }}>
      <Box sx={{ mb: 4 }}>
        <Button
          component={Link} to="/simulations"
          sx={{ color: ZB_COLORS.textMuted, fontFamily: "DM Sans", fontSize: "0.85rem", mb: 1.5, pl: 0 }}
        >
          ← Back to simulations
        </Button>
        <Typography variant="h4" sx={{ color: "#fff", mb: 0.5 }}>{sim.title}</Typography>
        <Typography sx={{ color: ZB_COLORS.textMuted, fontFamily: "DM Sans" }}>{sim.description}</Typography>
      </Box>

      <Box sx={{ mb: 4 }}>
        <Box sx={{ display: "flex", justifyContent: "space-between", mb: 1 }}>
          <Typography sx={{ fontSize: "0.8rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans" }}>
            Task {activeStep + 1} of {sim.tasks.length}
          </Typography>
          <Typography sx={{ fontSize: "0.8rem", color: ZB_COLORS.gold, fontFamily: "DM Sans", fontWeight: 600 }}>
            {Math.round((activeStep / sim.tasks.length) * 100)}% complete
          </Typography>
        </Box>
        <Box sx={{ height: 4, background: ZB_COLORS.border, borderRadius: 2, overflow: "hidden" }}>
          <Box
            sx={{
              width: `${(activeStep / sim.tasks.length) * 100}%`,
              height: "100%",
              background: ZB_COLORS.gold,
              borderRadius: 2,
              transition: "width 0.4s ease",
            }}
          />
        </Box>
      </Box>

      <Box
        sx={{
          background: ZB_COLORS.navyMid,
          border: `0.5px solid ${ZB_COLORS.border}`,
          borderRadius: "16px",
          p: { xs: 2.5, md: 4 },
        }}
      >
        <Chip
          label={`Task ${activeStep + 1}`}
          size="small"
          sx={{
            background: "rgba(255,214,0,0.1)",
            color: ZB_COLORS.gold,
            border: "0.5px solid rgba(255,214,0,0.3)",
            fontFamily: "DM Sans",
            mb: 2,
          }}
        />
        <Typography sx={{ color: "#fff", fontFamily: "DM Sans", fontSize: "1rem", lineHeight: 1.65, mb: 3 }}>
          {task.question}
        </Typography>

        <TextField
          label="Your answer"
          fullWidth
          multiline
          minRows={4}
          value={answers[task.id] || ""}
          onChange={e => setAnswers({ ...answers, [task.id]: e.target.value })}
          sx={{ mb: 2 }}
        />

        {task.fileType && (
          <Box sx={{ mb: 3 }}>
            <Typography sx={{ fontSize: "0.8rem", color: ZB_COLORS.textMuted, fontFamily: "DM Sans", mb: 1 }}>
              Optional: attach a file ({task.fileType.toUpperCase()})
            </Typography>
            <input
              type="file"
              accept={task.fileType.split(",").map(t => "." + t.trim()).join(",")}
              style={{ color: "rgba(255,255,255,0.6)", fontFamily: "DM Sans", fontSize: "0.875rem" }}
            />
          </Box>
        )}

        <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 1 }}>
          {activeStep > 0 && (
            <Button
              onClick={() => setActiveStep(prev => prev - 1)}
              sx={{ color: ZB_COLORS.textMuted, border: `0.5px solid ${ZB_COLORS.border}`, borderRadius: "8px", px: 2 }}
            >
              ← Previous
            </Button>
          )}
          <Button variant="contained" onClick={handleNext} sx={{ ml: "auto" }}>
            {isLast ? "Submit simulation" : "Next task →"}
          </Button>
        </Box>
      </Box>
    </Box>
  );
}
